n = int(input())
edges = [(1, 0, 1), (1, 1, 2), (1, 0, 2), (5, 2, 3)] if n == 1 else [(1, 0, 1), (1, 1, 2), (5, 2, 3)]
parent = list(range(4))
def root(x):
    while parent[x] != x:
        x = parent[x]
    return x
chosen = []
for weight, u, v in sorted(edges):
    if True:
        parent[root(u)] = root(v); chosen.append(weight)
        if len(chosen) == 3:
            break
print(f'cost={sum(chosen)} connected={len({root(x) for x in range(4)}) == 1}')

